"""Chapter 4 (part A): 4.1 intro / data status, 4.2 density, 4.3 compressive strength, 4.4 water absorption."""
from ch4_common import *

TESTED1 = ["NA", "RA", "Rab5", "Rab10", "Rab15"]
TESTED2 = ["RCA0", "RCA5", "RCA10", "RCA15"]
NAME1 = {"NA": "NA", "RA": "RA", "Rab5": "Rab5%", "Rab10": "Rab10%", "Rab15": "Rab15%"}
NAME2 = {"RCA0": "RCA 0%", "RCA5": "RCA 5%", "RCA10": "RCA 10%", "RCA15": "RCA 15%"}


def pgt(p):
    return "> 0.99" if p > 0.995 else f"= {p:.2f}"


def build(b, N):
    b.h1(4, "ผลการวิจัยและอภิปรายผล")

    # ------------------------------------------------------------------ 4.1
    b.h2("4.1 บทนำ")
    b.p("บทนี้นำเสนอผลการทดสอบสมบัติทางกายภาพและเชิงกลของคอนกรีตบล็อกปูพื้นที่ใช้เศษคอนกรีตเหลือทิ้ง (Recycled Concrete Aggregate: RCA) ร่วมกับถ่านชีวภาพจากไม้ไผ่ ตามอัตราส่วนผสมใน{tab:mix} การทดลองมี 2 ชุด ชุดที่ 1 คุมการแทนที่มวลรวมละเอียดด้วย RCA ที่ร้อยละ 50 และใช้ถ่านชีวภาพทดแทนซีเมนต์ร้อยละ 5 10 และ 15 เทียบกับสูตร RA ที่ไม่มีถ่านชีวภาพและสูตร NA ที่ใช้มวลรวมธรรมชาติทั้งหมด ชุดที่ 2 คุมปริมาณถ่านชีวภาพคงที่ 48 กรัมต่อก้อนและแทนที่ทรายด้วย RCA ร้อยละ 0 5 10 และ 15")
    b.p(ot(297, {"มอก. 827-2565": "มอก. 827-2565 {c:tis827}"}).replace("นอกจากนี้ยังได้เปรียบเทียบสมรรถนะของคอนกรีตบล็อกปูพื้นที่พัฒนาขึ้นกับผลิตภัณฑ์ที่จำหน่ายในท้องตลาด และศึกษาอิทธิพลของรูปทรงชิ้นทดสอบต่อค่ากำลังต้านทานแรงอัดที่วัดได้", "นอกจากนี้ได้เปรียบเทียบกับผลิตภัณฑ์ที่จำหน่ายในท้องตลาด ศึกษาอิทธิพลของรูปทรงชิ้นทดสอบ และเพิ่มการวิเคราะห์ความต้านทานการลื่นไถล การประเมินคาร์บอนเบื้องต้น และการเปรียบเทียบกับงานวิจัยอื่นที่ตรวจสอบแล้ว"))
    b.p("ผลในบทนี้มาจากสามแหล่งซึ่งมีความน่าเชื่อถือไม่เท่ากัน จึงแยกสถานะไว้ใน{tab:rdatastat} ค่าที่วัดคือค่าที่บันทึกในตารางผลทดสอบของร่างเดิมและไม่ได้แก้ไข ค่าคำนวณคือค่าที่ผู้วิจัยคำนวณใหม่จากค่าที่วัดหรือจากปริมาณวัสดุ ส่วนค่าสมมติ " + PH + " คือค่าที่ยังไม่มีการวัดจริง ใช้แสดงรูปแบบการรายงานและวิธีวิเคราะห์เท่านั้น ต้องแทนที่ด้วยข้อมูลจริงก่อนเผยแพร่ ตัวเลขที่เป็นค่าสมมติทุกตัวในรายงานนี้แสดงเป็นตัวหนาสีแดง")
    rows = [
        ["ความหนาแน่น ชุดที่ 1", "{tab:rdens}, {fig:rdens}", "ตารางผลทดสอบและภาคผนวก ก-1 ของร่างเดิม", "ค่าที่วัด"],
        ["กำลังอัด ชุดที่ 1 และ 2", "{tab:rfc1}, {tab:rfc2}", "ตารางผลทดสอบของร่างเดิม 40 ก้อน; 3 ก้อนไม่มีบันทึกต้นฉบับ", "ค่าที่วัด (3 ก้อนเป็น " + PH + ")"],
        ["ANOVA, Tukey HSD, แบบจำลองความแก่, การถดถอย", "{tab:ranova}, {tab:rkin}", "คำนวณใหม่จากค่ารายก้อน", "ค่าคำนวณ"],
        ["การดูดซึมน้ำ", "{tab:rabs1}, {tab:rabs2}", "ตารางผลทดสอบของร่างเดิม; 3 รายการผิดปกติ", "ค่าที่วัด (รอยืนยัน)"],
        ["การดูดซึมน้ำ ทดสอบซ้ำ", "ภาคผนวก ข", "ยังไม่ได้ทดสอบ", PH],
        ["ความต้านทานการลื่นไถล (BPN)", "{tab:rbpn}, {fig:rbpnbars}–{fign:rbpnrisk}", "ปรับจากค่าตัวอย่างในร่างเดิมที่ผู้วิจัยยืนยันว่าเป็นค่าสมมติ", PH],
        ["ผลิตภัณฑ์ท้องตลาด และชิ้นทรงลูกบาศก์", "{tab:rmkt}, {tab:rshape}", "ภาคผนวก ก-2 และ ก-3 ของร่างเดิม", "ค่าที่วัด"],
        ["การประเมินคาร์บอนเบื้องต้นและต้นทุน", "{tab:rinv}, {tab:rlca}", "แบบจำลองจากปริมาณวัสดุใน{tab:mix} และตัวประกอบใน{tab:ef}", "ค่าคำนวณ (บางตัวประกอบเป็น " + PH + ")"],
        ["การเปรียบเทียบกับงานวิจัยอื่น", "{tab:rlit}, {fig:rlitbc}, {fig:rlitrca}", "งานที่ตรวจสอบการมีอยู่แล้ว ({tab:sys})", "ข้อมูลอ้างอิง"],
    ]
    b.table("rdatastat", "สถานะข้อมูลของผลในบทที่ 4", ["รายการ", "ตาราง/ภาพ", "ที่มา", "สถานะ"], rows, [2500, 1900, 3300, 1700], align=["left", "left", "left", "left"], sz=20)
    b.p(ot(299, {"ชุดที่ 1 กำหนดให้ NA": "ชุดที่ 1 กำหนดให้ NA", "Rab5% Rab10% และ Rab15% หมายถึงคอนกรีตที่แทนที่ทรายด้วยถ่านชีวภาพจากไม้ไผ่ในอัตราร้อยละ 5 10 และ 15 ตามลำดับ": "Rab5% Rab10% และ Rab15% หมายถึงคอนกรีตที่ลดซีเมนต์ร้อยละ 5 10 และ 15 ของซีเมนต์สูตรควบคุม (600 กรัม) โดยเติมถ่านชีวภาพ 45 90 และ 135 กรัมต่อก้อนตามลำดับ ({tab:mixderived})", "ส่วนชุดที่ 2 ใช้สัญลักษณ์ BO-RE-XX-YY โดย BO หมายถึงไบโอชาร์ RE หมายถึงเศษคอนกรีตรีไซเคิล XX หมายถึงอายุการบ่ม (วัน) และ YY หมายถึงร้อยละของการแทนที่ทรายด้วยเศษคอนกรีตรีไซเคิล": "ส่วนชุดที่ 2 ใช้สัญลักษณ์ RCA0% RCA5% RCA10% และ RCA15% ตามร้อยละของทรายที่แทนด้วย RCA (ที่มาของรหัส BO-RE-XX-YY ในร่างเดิมอยู่ในภาคผนวก ก)"}))
    b.p("ภาพกราฟในบทนี้ใช้สีที่อ่านได้ชัดเมื่อพิมพ์ขาวดำและแยกอายุบ่มด้วยลวดลายของแท่ง แถบความคลาดเคลื่อนแสดงส่วนเบี่ยงเบนมาตรฐาน (standard deviation: SD) ของตัวอย่างในแต่ละสูตรและอายุ ซึ่งมีเพียง 3 ก้อน (บางกรณี 2 ก้อน) ค่า SD จึงมีความไม่แน่นอนสูง การเปรียบเทียบระหว่างสูตรใช้การวิเคราะห์ความแปรปรวนทางเดียว (one-way ANOVA) และการเปรียบเทียบเชิงคู่แบบ Tukey HSD ที่ระดับนัยสำคัญ 0.05 ร่วมกับขนาดอิทธิพล η<sup>2</sup> และไม่อ้างความแตกต่างจากค่าเฉลี่ยเพียงอย่างเดียว สูตร RA ที่อายุ 7 และ 14 วัน และสูตร NA ที่อายุ 14 วัน มีตัวอย่างที่ใช้วิเคราะห์เพียง 2 ก้อน (รายละเอียดในภาคผนวก ข ข้อ ข-4)")

    # ------------------------------------------------------------------ 4.2
    b.h2("4.2 ผลการทดสอบความหนาแน่นของคอนกรีตบล็อกปูพื้น")
    b.p(ot(302, {"ตามสมการที่ 3-1": "ตาม{eq:dens}", "ตารางที่ 4-1 และภาพที่ 4-1": "{tab:rdens} และ{fig:rdens}"}))
    dens = pd.read_csv(os.path.join(DATA, "density_table4-1.csv"))
    sd28 = D[D.age_d == 28].groupby("mix").density.std()
    mp = dict(zip(dens.mix, TESTED1))
    rows = []
    for _, r in dens.iterrows():
        m = mp[r.mix]; rows.append([NAME1[m], d0(r.d7), d0(r.d14), d0(r.d28), d0(sd28[m]), d0(r.overall_reported), "—" if m in ("NA", "RA") else f"{pct(r.overall_reported, dens.overall_reported[1]):+.1f}".replace("-", "\u2212")])
    b.table("rdens", "ผลการทดสอบความหนาแน่นของคอนกรีตบล็อกปูพื้น ชุดที่ 1 (กก./ม.<sup>3</sup>)", ["สูตร", "7 วัน", "14 วัน", "28 วัน", "SD (28 วัน)", "เฉลี่ยรวม", "เทียบ RA (%)"], rows, [1500, 1150, 1150, 1150, 1250, 1300, 1400], sz=21,
            note="หมายเหตุ ค่าเฉลี่ยรวมเป็นค่าที่รายงานในร่างเดิม สำหรับสูตร RA ที่อายุบ่ม 7 วัน มีตัวอย่างที่ใช้คำนวณได้เพียง 2 ก้อน ค่าเฉลี่ยรวมที่รายงาน (2,204 กก./ม.³) จึงต่างจากค่าเฉลี่ยเลขคณิตของค่าทั้งสามอายุ (2,195 กก./ม.³) SD คำนวณจากค่ารายก้อนในภาคผนวก ก-1")
    b.fig("rdens", fp("r_density_s1"), 15.0, "ความหนาแน่นของคอนกรีตบล็อกปูพื้น ชุดที่ 1 (ก) ตามสูตรและอายุบ่ม (ข) ตามระดับการลดซีเมนต์ ผู้วิจัยสร้างภาพจากข้อมูลใน{tab:rdens} และภาคผนวก ก-1")
    sl, r2, p = dens_fit()
    F28, p28 = dens_anova(28)
    b.p(f"ความหนาแน่นลดลงเมื่อเพิ่มอัตราการทดแทนซีเมนต์ด้วยถ่านชีวภาพ ค่าเฉลี่ยรวมของสูตร NA RA Rab5% Rab10% และ Rab15% เท่ากับ {d0(N['rho_all_NA'])} {d0(N['rho_all_RA'])} {d0(N['rho_all_Rab5'])} {d0(N['rho_all_Rab10'])} และ {d0(N['rho_all_Rab15'])} กก./ม.<sup>3</sup> ตามลำดับ เมื่อถดถอยความหนาแน่นรายก้อนของสูตรชุด RCA ร้อยละ 50 (RA ถึง Rab15%) กับระดับการลดซีเมนต์ ได้ความชัน {sl:.1f} กก./ม.<sup>3</sup> ต่อร้อยละ 1 (R<sup>2</sup> = {r2:.2f}, p {pv(p)}) ที่อายุ 28 วัน ความหนาแน่นต่างกันระหว่างสูตรอย่างมีนัยสำคัญ (F = {F28:.1f}, p {pv(p28)}) การสูญเสียความหนาแน่นนี้สอดคล้องกับธรรมชาติของถ่านชีวภาพซึ่งเป็นอนุภาคพรุนและมีความหนาแน่นอนุภาคต่ำกว่าซีเมนต์ที่ถูกแทนที่ ({{c:zhang2022,barbhuiya2024}}) ส่วนสูตร NA มีความหนาแน่นสูงกว่า RA ราว {pct(N['rho_all_NA'], N['rho_all_RA']):.0f} % ซึ่งสอดคล้องกับที่ RCA มีมอร์ตาร์เดิมเกาะผิวและพรุนกว่ามวลรวมธรรมชาติ ({{c:verian2018,silva2014}})")
    b.p("เมื่อพิจารณาตามอายุบ่ม ความหนาแน่นของ NA และ RA สูงขึ้นจาก 7 เป็น 14 วันแล้วคงที่ที่ 28 วัน ส่วนสูตรที่ผสมถ่านชีวภาพเปลี่ยนตามอายุน้อย ข้อสังเกตสองข้อที่ควรระวังคือ ประการแรก ตัวอย่างต่างอายุเป็นก้อนต่างกัน (ไม่ได้ชั่งก้อนเดิมซ้ำ) ความแตกต่างระหว่างอายุจึงปนกับความแปรปรวนของการอัดขึ้นรูปและความชื้นในก้อน (SD ราว 15–55 กก./ม.<sup>3</sup>) ประการที่สอง ร่างเดิมไม่ระบุว่าชั่งในสภาพอบแห้งหรือสภาพที่ได้รับมา ความหนาแน่นที่รายงานจึงตีความเป็นความหนาแน่นที่ความชื้นปัจจุบันของก้อน " + PH + " ความหนาแน่นของ Rab15% ที่สูงกว่า Rab10% เล็กน้อยอยู่ในช่วงความคลาดเคลื่อนของการวัด (SD ของ Rab10% ที่ 28 วันคือ " + d0(sd28["Rab10"]) + " กก./ม.<sup>3</sup>) จึงไม่ควรตีความว่าเป็นแนวโน้มจริง ค่าความหนาแน่นทั้งหมดอยู่ในช่วงของคอนกรีตน้ำหนักปกติ")

    # ------------------------------------------------------------------ 4.3
    b.h2("4.3 ผลการทดสอบกำลังต้านทานแรงอัด")
    L = strength_long()
    S1 = S[S.series == "I"]; S2 = S[S.series == "II"]

    def cell(series, mix, age, spec, dec):
        r = L[(L.series == series) & (L.mix == mix) & (L.age == age) & (L.spec == spec)].iloc[0]
        t = f"{r.fc:.{dec}f}"
        return f"<ph>{t}</ph>†" if r.placeholder else t

    def strength_rows(series, order, names, dec):
        rows = []
        cd28 = cld(series, 28, order)
        for m in order:
            for age in (7, 14, 28):
                row = S[(S.series == series) & (S.mix == m) & (S.age == age)].iloc[0]
                rows.append([names[m] if age == 7 else "", str(age), cell(series, m, age, "s1", dec), cell(series, m, age, "s2", dec), cell(series, m, age, "s3", dec),
                             f"{row.mean_reported:.2f}", f"{row.sd:.2f}", f"{row.cv_pct:.1f}", cd28[m] if age == 28 else ""])
        return rows

    hdr = ["สูตร", "อายุ (วัน)", "ก้อนที่ 1", "ก้อนที่ 2", "ก้อนที่ 3", "เฉลี่ย (รายงาน)", "SD", "CV (%)", "กลุ่ม Tukey (28 วัน)"]
    b.h3("4.3.1 ชุดที่ 1 : ถ่านชีวภาพทดแทนซีเมนต์ ภายใต้การแทนที่มวลรวมละเอียดด้วย RCA ร้อยละ 50")
    b.p(ot(312, {"ตามสมการที่ 3-2": "ตาม{eq:comp}", "ตารางที่ 4-2 ภาพที่ 4-2 และภาพที่ 4-3": "{tab:rfc1} {fig:rfc1} และ{fig:rfc1dev}"}))
    b.table("rfc1", "ผลการทดสอบกำลังต้านทานแรงอัด (MPa) ของคอนกรีตบล็อกปูพื้น ชุดที่ 1", hdr, strength_rows("I", TESTED1, NAME1, 0), [1250, 780, 880, 880, 880, 1150, 780, 780, 1500], sz=20,
            note="หมายเหตุ ค่ารายก้อนในร่างเดิมบันทึกเป็นจำนวนเต็ม ค่าเฉลี่ยที่รายงานคำนวณจากค่าที่ยังไม่ปัดเศษ SD และ CV คำนวณจากค่ารายก้อนที่แสดง กลุ่ม Tukey คืออักษรกำกับ สูตรที่มีอักษรร่วมกันไม่ต่างกันที่ระดับ 0.05 † ช่องที่ร่างเดิมแสดงตัวเลขแต่ไม่มีบันทึกต้นฉบับ (ค่าเฉลี่ยที่รายงานตรงกับ n = 2) จึงเป็นค่าสมมติ " + PH + " และไม่ถูกนำไปคำนวณ SD ANOVA และ Tukey")
    b.fig("rfc1", fp("r_fc_s1_bars"), 14.5, "กำลังต้านทานแรงอัดของคอนกรีตบล็อกปูพื้น ชุดที่ 1 ตามสูตรและอายุบ่ม ตัวเลขบนแท่งคือค่าเฉลี่ยที่ 28 วัน เส้นประคือเกณฑ์ มอก. 827-2565 และ มอก. 2035-2565 ผู้วิจัยสร้างภาพจาก{tab:rfc1}")
    b.p(f"ที่อายุ 28 วัน สูตร RA Rab5% Rab10% และ Rab15% มีกำลังอัดเฉลี่ย {f2(N['fc28_RA'])} {f2(N['fc28_Rab5'])} {f2(N['fc28_Rab10'])} และ {f2(N['fc28_Rab15'])} MPa ตามลำดับ คิดเป็นการลดลง {abs(pct(N['fc28_Rab5'], N['fc28_RA'])):.1f} % {abs(pct(N['fc28_Rab10'], N['fc28_RA'])):.1f} % และ {abs(pct(N['fc28_Rab15'], N['fc28_RA'])):.1f} % เมื่อเทียบกับ RA ส่วน NA ให้ {f2(N['fc28_NA'])} MPa สูงกว่า RA ร้อยละ {pct(N['fc28_NA'], N['fc28_RA']):.0f} ผล ANOVA ที่ 28 วันยืนยันว่าสูตรต่างกัน (F({4},{N['df2_I_28']}) = {N['F_I_28']:.1f}, p {pv(N['p_I_28'])}, η<sup>2</sup> = {N['eta_I_28']:.2f}) และ Tukey HSD แยกได้สามกลุ่ม คือ NA สูงที่สุด RA อยู่กลาง และ Rab10% กับ Rab15% ต่ำที่สุดโดยไม่ต่างกันเอง (p {pgt(tp('I',28,'Rab10','Rab15'))}) สูตร Rab5% ไม่ต่างจาก RA อย่างมีนัยสำคัญ (p = {tp('I',28,'RA','Rab5'):.2f}) แต่ผลต่างเฉลี่ย {abs(N['fc28_Rab5'] - N['fc28_RA']):.1f} MPa ไม่น้อย และการทดสอบมีเพียง 3 ก้อนต่อสูตร กำลังตรวจจับความต่างจึงต่ำ จึงไม่ควรสรุปว่า Rab5% มีกำลังเท่ากับ RA")
    S28 = S1[S1.age == 28].set_index("mix")
    b.h3("การเทียบกับเกณฑ์มาตรฐาน")
    b.p(f"ทุกสูตรที่ 28 วันผ่านเกณฑ์ของ มอก. 827-2565 ({TIS827_MPa:.0f} MPa) ทั้งค่าเฉลี่ยและค่ารายก้อน (ก้อนต่ำสุดคือ {S28.loc['Rab10','mn']:.0f} MPa ในสูตร Rab10%) ส่วนเกณฑ์ของ มอก. 2035-2565 สำหรับงานหนัก ({TIS2035_MPa:.0f} MPa) ร่างเดิมระบุว่าผ่านเฉพาะสูตร RA แต่เมื่อตรวจกับตารางผลพบว่าสูตร Rab5% ซึ่งมีค่าเฉลี่ย {f2(N['fc28_Rab5'])} MPa และทั้งสามก้อนไม่ต่ำกว่า {S28.loc['Rab5','mn']:.0f} MPa ก็ผ่านเช่นกัน รวมทั้ง NA ด้วย สูตร Rab10% และ Rab15% ไม่ผ่านเกณฑ์งานหนักแต่ผ่านเกณฑ์ทั่วไป ข้อความนี้แก้ไขจากร่างเดิม (ผู้วิจัยตรวจกับ{{tab:std}} ซึ่งยังต้องยืนยันกับฉบับจริงของมาตรฐาน) ที่อายุ 7 วัน สูตร RA Rab10% และ Rab15% มีค่าเฉลี่ยต่ำกว่า 35 MPa แต่ Rab5% ({f2(N['fc7_Rab5'])} MPa) สูงกว่า ซึ่งสวนทางกับลำดับที่อายุ 28 วัน ผู้วิจัยพบว่าค่าของ RA ที่ 7 วันมีเพียง 2 ก้อนและต่ำผิดปกติเมื่อเทียบกับอายุอื่น จึงไม่นำไปสรุปว่า Rab5% พัฒนากำลังต้นอายุได้ดีกว่า (ดูหัวข้อ 4.3.3)")
    b.fig("rfc1dev", fp("r_fc_s1_dev"), 12.5, "การพัฒนากำลังต้านทานแรงอัดตามอายุบ่มของคอนกรีตบล็อกปูพื้น ชุดที่ 1 แถบคือ ±1 SD เส้นประคือเกณฑ์ มอก. 827-2565 และ มอก. 2035-2565")
    b.h3("กลไกที่เป็นไปได้ของกำลังอัดที่ลดลง")
    b.p("ร่างเดิมอธิบายการลดลงของกำลังด้วยโครงสร้างพรุนของถ่านชีวภาพเพียงอย่างเดียว การวิเคราะห์ใหม่แยกได้อย่างน้อยสองส่วน ส่วนแรกคือซีเมนต์ที่หายไป ถ้ากำลังอัดของสูตรชุดนี้ขึ้นกับปริมาณซีเมนต์เป็นหลัก การถดถอยเชิงเส้นของกำลังอัด 28 วันกับปริมาณซีเมนต์ของสูตร RA ถึง Rab15% (n = 4 ค่าเฉลี่ย) ให้ความชัน " + f"{N['b_cem']:.2f} MPa ต่อ กก./ม.<sup>3</sup> (R<sup>2</sup> = {N['r2_cem']:.2f})" + " ส่วนที่สองคือผลของอนุภาคถ่านชีวภาพเอง ซึ่งเพิ่มช่องว่างและลดความหนาแน่น ดังที่ {c:wang2020,zhang2022} อธิบายว่าปริมาณสูงทำให้กำลังลดเพราะโครงสร้างพรุนและเปราะของถ่าน")
    cm = {m: N[f"cem_{m}"] for m in ("RA", "Rab5", "Rab10", "Rab15")}
    rows = []
    for m in ("Rab5", "Rab10", "Rab15"):
        dc = cm["RA"] - cm[m]; pred = N["b_cem"] * dc; obs = N["fc28_RA"] - N[f"fc28_{m}"]
        rows.append([NAME1[m], f"{dc:.1f}", f"{pred:.1f}", f"{obs:.1f}", f"{obs - pred:+.1f}", f"{N['bi_'+m]:.2f}"])
    b.table("rcem", "การแยกส่วนของกำลังอัดที่ลดลง (28 วัน) เทียบกับสูตร RA", ["สูตร", "ซีเมนต์ที่ลดลง\n(กก./ม.³)", "กำลังที่ลดลงตามที่\nซีเมนต์อธิบาย (MPa)", "กำลังที่ลดลงจริง\n(MPa)", "ส่วนเกิน\n(MPa)", "bi\n(กก./ม.³ ต่อ MPa)"], rows, [1500, 1500, 1750, 1500, 1200, 1550], sz=20,
            note="หมายเหตุ ค่าที่ซีเมนต์อธิบายคำนวณจากความชันของการถดถอยกับปริมาณซีเมนต์ของ RA–Rab15% (n = 4) ซึ่งเป็นความสัมพันธ์เชิงประจักษ์ของสูตรชุดนี้เท่านั้น ส่วนเกินที่เป็นบวกหมายถึงกำลังที่สูญเสียมากกว่าที่ปริมาณซีเมนต์ที่ลดลงอธิบายได้")
    b.p(f"ที่ระดับ Rab5% การลดลงของกำลังจริงใกล้เคียงกับที่ซีเมนต์อธิบายได้ ({rows[0][2]} เทียบ {rows[0][3]} MPa) ที่ระดับ Rab10% กำลังจริงต่ำกว่าที่ซีเมนต์อธิบายอีก {rows[1][4].lstrip('+')} MPa ซึ่งชี้ว่ามีผลเพิ่มจากอนุภาคถ่านชีวภาพ ที่ระดับ Rab15% กำลังจริงลดน้อยกว่าที่คาดจากซีเมนต์ ({rows[2][4]} MPa) ซึ่งตีความได้ว่าเป็นความแปรปรวนของตัวอย่าง (Rab10% CV = {N['cv28_Rab10']:.1f} %) และสะท้อนว่าความสัมพันธ์จากค่าเฉลี่ย 4 จุดไม่ควรใช้ทำนายนอกช่วง ข้อควรระวังคือในสูตรชุดนี้ซีเมนต์ที่ลดและไบโอชาร์ที่เติมเปลี่ยนไปพร้อมกันในสัดส่วนคงที่ (ไบโอชาร์ 1.5 เท่าของซีเมนต์ที่ลด) ทางสถิติจึงแยกผลของสองตัวแปรนี้จากกันไม่ได้ {{tab:rcem}} เป็นเพียงการเทียบขนาด ไม่ใช่การแยกเชิงสาเหตุ (ข้อความส่วนนี้เป็นการตีความของผู้วิจัย) ดัชนี bi เพิ่มจาก {N['bi_RA']:.2f} (RA) เป็น {N['bi_Rab5']:.2f} {N['bi_Rab10']:.2f} และ {N['bi_Rab15']:.2f} กก./ม.<sup>3</sup> ต่อ MPa ในสูตรที่ผสมถ่านชีวภาพ หมายความว่าซีเมนต์ที่เหลือถูกใช้ให้กำลังได้น้อยลง ตามเกณฑ์เทียบของ Damineli และคณะ {{c:damineli2010}} ที่ bi ประมาณ 5 สำหรับคอนกรีตกำลังเกิน 50 MPa สูตร NA ({N['bi_NA']:.2f}) อยู่ในระดับดี ขณะที่สูตรที่ใช้ RCA ทั้งหมดสูงกว่า")
    b.fig("rfc1rel", fp("r_fc_s1_rel"), 14.5, "(ก) กำลังอัดของสูตรผสมถ่านชีวภาพเทียบกับ RA ที่อายุเดียวกัน (ข) กำลังอัดที่ 28 วันต่อซีเมนต์ 100 กก. ต่อลูกบาศก์เมตร ผู้วิจัยคำนวณจาก{tab:rfc1} และ{tab:rinv}")
    b.p(ot(323, {"ตารางที่ 3-1": "{tab:mix}"}).replace("ผลการทดสอบที่รวบรวมได้ในรอบการรายงานนี้ครอบคลุมเฉพาะอัตราร้อยละ 0 ถึง 15 เท่านั้น", "ผลการทดสอบที่รวบรวมได้ในรอบการรายงานนี้ครอบคลุมเฉพาะอัตราร้อยละ 0 ถึง 15 เท่านั้น ผลที่ร้อยละ 10 และ 15 ชี้ว่ากำลังลดลงช้าลงหลังร้อยละ 10 แต่มีเพียงสองระดับและ n = 3 จึงไม่พอสรุปว่ากำลังคงที่ การทดสอบที่ร้อยละ 20 และ 25 จะใช้ยืนยันแนวโน้มนี้ (ข้อความส่วนนี้เป็นข้อสังเกตของผู้วิจัย)"))

    # ---- series II
    b.h3("4.3.2 ชุดที่ 2 : แทนที่ทรายด้วยเศษคอนกรีตรีไซเคิล ภายใต้ปริมาณถ่านชีวภาพคงที่")
    b.p(ot(325, {"ตารางที่ 4-3 ภาพที่ 4-4 และภาพที่ 4-5": "{tab:rfc2} {fig:rfc2} และ{fig:rfc2dev}"}))
    b.table("rfc2", "ผลการทดสอบกำลังต้านทานแรงอัด (MPa) ของคอนกรีตบล็อกปูพื้น ชุดที่ 2", hdr, strength_rows("II", TESTED2, NAME2, 2), [1250, 780, 880, 880, 880, 1150, 780, 780, 1500], sz=20,
            note="หมายเหตุ ค่าเฉลี่ยตรงกับค่าดิบรายก้อนทุกค่า (ต่างจากข้อความใต้ภาพของร่างเดิมที่ระบุค่า 7 วันเป็น 19.54 21.17 23.80 และ 28.70 MPa ซึ่งไม่ตรงกับตาราง ดูภาคผนวก ข ข้อ ข-1) กลุ่ม Tukey ใช้ตัวอักษรกำกับแบบเดียวกับ " + "{tab:rfc1}")
    b.fig("rfc2", fp("r_fc_s2_bars"), 14.5, "กำลังต้านทานแรงอัดของคอนกรีตบล็อกปูพื้น ชุดที่ 2 ตามสูตรและอายุบ่ม ผู้วิจัยสร้างภาพจาก{tab:rfc2}")
    c2 = N['fc28_RCA15']
    b.p(f"ที่อายุ 28 วัน สูตรที่แทนที่ทรายด้วย RCA ร้อยละ 0 5 10 และ 15 มีกำลังอัดเฉลี่ย {f2(N['fc28_RCA0'])} {f2(N['fc28_RCA5'])} {f2(N['fc28_RCA10'])} และ {f2(c2)} MPa ตามลำดับ ทุกสูตรผ่านทั้งเกณฑ์ มอก. 827-2565 และ มอก. 2035-2565 ผล ANOVA ที่ 28 วันมีนัยสำคัญ (F(3,{N['df2_II_28']}) = {N['F_II_28']:.1f}, p = {N['p_II_28']:.3f}, η<sup>2</sup> = {N['eta_II_28']:.2f}) โดย RCA10% และ RCA15% สูงกว่า RCA0% อย่างมีนัยสำคัญ (p = {tp('II',28,'RCA0','RCA10'):.3f} และ {tp('II',28,'RCA0','RCA15'):.3f}) ส่วน RCA5% ไม่ต่างจากทั้งสองกลุ่ม (p = {tp('II',28,'RCA0','RCA5'):.3f} เทียบ RCA0%) กำลังที่ร้อยละ 15 สูงกว่าร้อยละ 0 อยู่ {pct(c2, N['fc28_RCA0']):.1f} % ที่อายุ 14 วัน ANOVA ไม่มีนัยสำคัญ (p = {N['p_II_14']:.2f}) เพราะสูตร RCA0% และ RCA5% มี CV สูงถึง {N['cv14_RCA0']:.1f} % และ {N['cv14_RCA5']:.1f} % ที่อายุ 7 วัน RCA15% สูงกว่าสูตรอื่นอย่างมีนัยสำคัญ และเป็นสูตรเดียวที่มีค่าเฉลี่ยเกิน 35 MPa ({f2(N['fc7_RCA15'])} MPa)")
    b.fig("rfc2dev", fp("r_fc_s2_dev"), 12.5, "การพัฒนากำลังต้านทานแรงอัดตามอายุบ่มของคอนกรีตบล็อกปูพื้น ชุดที่ 2 แถบคือ ±1 SD เส้นประคือเกณฑ์ มอก. 827-2565 และ มอก. 2035-2565")
    b.fig("rfc2rel", fp("r_fc_s2_rel"), 14.5, "(ก) กำลังอัดเทียบกับ RCA 0% ที่อายุเดียวกัน (ข) อัตราส่วนกำลังระหว่างอายุ (14 วันต่อ 7 วัน และ 28 วันต่อ 14 วัน) แถบเทาคือช่วง 1.10–1.35 ที่ผู้วิจัยกำหนดให้ครอบคลุมค่าที่ EN 1992-1-1 ทำนายสำหรับ s = 0.20–0.38 ผู้วิจัยคำนวณจาก{tab:rfc2}")
    b.p("แนวโน้มของชุดที่ 2 ตรงข้ามกับชุดที่ 1 และยังต่างจากงานส่วนใหญ่ที่รายงานว่า RCA ทำให้กำลังของบล็อกปูพื้นลดลง เช่น Wang และคณะ (2019) {c:wangx2019} Rodríguez และคณะ (2017) {c:rodriguez2017} และ Poon และ Chan (2006) {c:poon2006} ผู้วิจัยจึงมองว่าผลนี้ต้องอธิบายอย่างระมัดระวัง กลไกที่ร่างเดิมเสนอคือรูปทรงเหลี่ยมมุมที่เพิ่มการยึดเกาะเชิงกล และปูนซีเมนต์ที่ยังไม่ทำปฏิกิริยาบนผิว RCA ซึ่งทำปฏิกิริยาต่อ ทั้งสองข้อมีเหตุผลทางวัสดุ แต่ต้องเพิ่มกลไกที่ชุดข้อมูลนี้แยกไม่ได้อีกอย่างน้อยสองข้อ ข้อแรก RCA ละเอียดที่แทนทรายมีขนาดคละต่างจากทราย จึงเปลี่ยนการเรียงตัวของอนุภาคและความแน่นในการอัดขึ้นรูป ข้อที่สอง RCA ดูดน้ำสูงกว่าทราย ({c:nedeljkovic2021}) จึงอาจลดน้ำอิสระและอัตราส่วนน้ำต่อวัสดุประสานที่มีผลจริงในส่วนผสมแห้งที่อัดขึ้นรูป ทั้งสี่ข้อยังไม่ได้ทดสอบ การยืนยันต้องวัดขนาดคละ การดูดซึมน้ำของ RCA และความหนาแน่นสดของส่วนผสมทุกสูตร (ข้อความส่วนนี้เป็นการตีความและข้อเสนอแนะของผู้วิจัย) นอกจากนี้ ตัวเลขชุดที่ 2 ทั้งหมดอยู่ที่ RCA ไม่เกินร้อยละ 15 ของทราย ซึ่งต่ำกว่าช่วงที่งานอื่นทดสอบ ({c:contreras2022,rodriguez2017}) จึงไม่ควรขยายผลไปยังอัตราที่สูงกว่านี้")
    b.p(ot(334, {"จากภาพที่ 4-5": "จาก{fig:rfc2rel}", "ซึ่งเป็นพฤติกรรมการพัฒนากำลังที่สอดคล้องกับคอนกรีตทั่วไปที่ใช้ปูนซีเมนต์ปอร์ตแลนด์ประเภทที่ 1": "อัตราส่วนนี้สูงกว่าที่แบบจำลองความแก่ของ EN 1992-1-1 ทำนายไว้ (ประมาณ 1.1 ถึง 1.3 เท่า สำหรับ s = 0.20–0.38) มาก (ดูหัวข้อ 4.3.3)", "โดยเพิ่มขึ้นประมาณ 1.6 ถึง 2.0 เท่า แล้วเพิ่มขึ้นในอัตราที่ลดลงในช่วงอายุ 14 ถึง 28 วัน": "โดยเพิ่มขึ้นประมาณ 1.6 ถึง 2.0 เท่า แล้วเพิ่มขึ้นในอัตราที่ลดลงในช่วงอายุ 14 ถึง 28 วัน (1.14 ถึง 1.22 เท่า)"}))

    # ---- kinetics
    b.h3("4.3.3 การพัฒนากำลังตามอายุและการตรวจความสอดคล้องของข้อมูล")
    b.p("เพื่อตรวจว่าการพัฒนากำลังของแต่ละสูตรสมเหตุสมผลหรือไม่ ผู้วิจัยปรับสมการความแก่ {eq:maturity} เข้ากับกำลังอัดที่ 7 14 และ 28 วันของแต่ละสูตรและหาค่า s ที่เหมาะที่สุด แล้วเทียบกับช่วง s = 0.20–0.38 ที่ EN 1992-1-1 {c:en1992} ให้ไว้สำหรับซีเมนต์ชนิดต่าง ๆ (ยังต้องตรวจกับฉบับจริง) ผลสรุปใน{tab:rkin} และ{fig:rkin}")
    fit = pd.read_csv(os.path.join(DATA, "stats_maturity_fits.csv"), keep_default_na=False)
    rows = []
    fit = fit.assign(_o=fit['mix'].map({m: i for i, m in enumerate(TESTED1 + TESTED2)})).sort_values('_o')
    for r in fit.itertuples():
        nm = NAME1.get(r.mix) or NAME2.get(r.mix)
        flag = "ในช่วง" if r.s_fit <= 0.45 else ("สูงกว่าช่วง" if r.s_fit <= 0.6 else "สูงกว่าช่วงมาก")
        rows.append([nm, f"{r.f7_f28:.2f}", f"{r.f14_f28:.2f}", f"{r.s_fit:.2f}", flag])
    b.table("rkin", "สัดส่วนกำลังต้นอายุต่อกำลัง 28 วัน และค่า s ที่ปรับเข้ากับสมการความแก่", ["สูตร", "f(7)/f(28)", "f(14)/f(28)", "s ที่ปรับ", "เทียบกับช่วง 0.20–0.38"], rows, [1800, 1500, 1500, 1500, 2500], sz=21,
            note="หมายเหตุ s ปรับด้วยวิธีกำลังสองน้อยที่สุดจากสามอายุ สูตรที่มีเพียงสามจุดข้อมูลทำให้ค่า s ไม่เสถียร การจัดประเภท \"สูงกว่าช่วง\" ใช้เกณฑ์ s > 0.45 เป็นเกณฑ์สะดวกของผู้วิจัย ไม่ใช่เกณฑ์ของมาตรฐาน")
    b.fig("rkin", fp("r_kinetics"), 15.0, "กำลังอัดที่อายุต่าง ๆ ต่อกำลังที่ 28 วัน เทียบกับแบบจำลองความแก่ของ EN 1992-1-1 (เส้นประคือ s = 0.25 แถบเทาคือ s = 0.20–0.38) (ก) ชุดที่ 1 (ข) ชุดที่ 2 ผู้วิจัยคำนวณจาก{tab:rfc1} และ{tab:rfc2}")
    b.p(f"สูตร NA Rab5% Rab10% และ Rab15% ให้ s = {N['s_NA']:.2f} {N['s_Rab5']:.2f} {N['s_Rab10']:.2f} และ {N['s_Rab15']:.2f} ซึ่งอยู่ในหรือใกล้ช่วงอ้างอิง แสดงว่าพัฒนาการกำลังของสูตรเหล่านี้สมเหตุสมผล ส่วนสูตร RA ({N['s_RA']:.2f}) และทุกสูตรของชุดที่ 2 ({N['s_RCA0']:.2f} {N['s_RCA5']:.2f} {N['s_RCA10']:.2f} {N['s_RCA15']:.2f}) สูงกว่าช่วงมาก กำลังที่ 7 วันของสูตรเหล่านี้จึงเป็นเพียงร้อยละ {N['fc7_RCA0']/N['fc28_RCA0']*100:.0f}–{N['fc7_RCA15']/N['fc28_RCA15']*100:.0f} ของกำลังที่ 28 วัน ส่วน RA ได้ร้อยละ {N['fc7_RA']/N['fc28_RA']*100:.0f}")
    b.p("การพัฒนากำลังช้าเช่นนี้เกิดได้จากสาเหตุสองกลุ่ม กลุ่มแรกเป็นเรื่องวัสดุและการบ่ม เช่น ซีเมนต์ที่พัฒนากำลังช้า การบ่มที่อุณหภูมิต่ำหรือความชื้นไม่สม่ำเสมอ และการที่ RCA ดูดน้ำจากเพสต์ในช่วงต้น กลุ่มที่สองเป็นเรื่องการออกแบบการทดลอง คือ ก้อนทดสอบแต่ละอายุเป็นคนละก้อน อาจหล่อต่างวันหรือต่างชุดผสม ความแตกต่างของอายุจึงปนกับความแตกต่างของชุดผสม ข้อมูลที่มีไม่พอแยกสองกลุ่มนี้ได้ ผู้วิจัยจึงระบุเพียงว่าค่าต้นอายุของ RA และชุดที่ 2 ต้องตรวจสอบ และเสนอให้ตรวจโดยหล่อก้อนทุกอายุจากชุดผสมเดียวกันและบันทึกอุณหภูมิบ่ม ข้อสรุปเรื่องสมรรถนะที่ 28 วันไม่ขึ้นกับประเด็นนี้ แต่การอ้างกำลังต้นอายุเพื่อกำหนดเวลาขนส่งหรือรื้อแบบต้องรอผลยืนยัน")

    # ---- strength-density
    b.h3("4.3.4 ความสัมพันธ์ระหว่างกำลังอัด ความหนาแน่น และปริมาณซีเมนต์")
    b.p(f"{{fig:rfcdens}}(ก) แสดงกำลังอัดทุกอายุของสูตรชุดที่ 1 เทียบกับความหนาแน่น การถดถอยแบบกำลัง ln f<sub>c</sub> = ln a + n ln ρ ให้ n = {N['b_rho_all']:.1f} (R<sup>2</sup> = {N['r2_rho_all']:.2f}, 15 จุด) เมื่อใช้อายุ 28 วันอย่างเดียว n = {N['b_rho_28']:.1f} (R<sup>2</sup> = {N['r2_rho_28']:.2f}, 5 จุด) ค่า n ราว 6 หมายความว่าความหนาแน่นที่ลดลงร้อยละ 1 สัมพันธ์กับกำลังที่ลดลงราวร้อยละ 6 ซึ่งเป็นดัชนีความไวของกำลังต่อความหนาแน่นตาม{{eq:reldens}} ไม่ใช่ค่าคงที่ของวัสดุ ผู้วิจัยจึงไม่เทียบกับค่าคงที่ที่อื่นโดยตรง")
    b.fig("rfcdens", fp("r_fc_density"), 15.0, "(ก) กำลังอัดเทียบกับความหนาแน่นของสูตรชุดที่ 1 ทุกอายุบ่ม พร้อมเส้นถดถอยแบบกำลัง (ข) กำลังอัดที่ 28 วันเทียบกับปริมาณซีเมนต์ต่อลูกบาศก์เมตร ผู้วิจัยคำนวณจาก{tab:rfc1} {tab:rdens} และ{tab:rinv}")
    b.p(f"{{fig:rfcdens}}(ข) ตั้งปริมาณซีเมนต์ต่อลูกบาศก์เมตรของบล็อก (คำนวณจากปริมาตรก้อน 0.00156 ลบ.ม. ตามที่อธิบายในหัวข้อ 3.7) เทียบกับกำลังที่ 28 วัน สูตร RA ถึง Rab15% เรียงตัวใกล้เส้นตรง (ความชัน {N['b_cem']:.2f} MPa ต่อ กก./ม.<sup>3</sup>, R<sup>2</sup> = {N['r2_cem']:.2f}, p = {N['reg'].iloc[2].p:.3f}, n = 4) แต่ NA อยู่เหนือเส้นนี้มาก แสดงว่าการเปลี่ยนมวลรวมธรรมชาติเป็น RCA ลดกำลังโดยที่ปริมาณซีเมนต์ไม่เปลี่ยน ผลจาก RCA จึงไม่ได้มาจากปริมาณซีเมนต์")
    b.fig("rporo", fp("r_porosity_model"), 11.5, "ความสัมพันธ์ระหว่างกำลังอัดสัมพัทธ์และความหนาแน่นสัมพัทธ์ที่ 28 วัน (อ้างอิง NA) เส้นประแสดงรูปแบบ f/f<sub>NA</sub> = (ρ/ρ<sub>NA</sub>)<sup>n</sup> เมื่อ n = 4 6 และ 8 และเส้นทึบคือผลปรับเข้ากับข้อมูลทั้งห้าสูตร ผู้วิจัยคำนวณ")
    b.p("{fig:rporo} แยกบทบาทของสองวัสดุได้ชัดขึ้น สูตร Rab5% Rab10% และ Rab15% อยู่ใกล้เส้นปรับเข้า แสดงว่ากำลังที่ลดลงของสูตรผสมถ่านชีวภาพสัมพันธ์กับความหนาแน่นที่ลดลงอย่างสม่ำเสมอ สูตร RA อยู่ต่ำกว่าเส้นอย่างชัดเจน กล่าวคือกำลังลดลงมากทั้งที่ความหนาแน่นเกือบเท่า NA ซึ่งสอดคล้องกับที่ RCA ลดกำลังผ่านกลไกอื่นนอกเหนือจากความพรุนรวม เช่น บริเวณรอยต่อ ITZ ที่พรุนและอ่อน ({c:scrivener2004,xiao2013}) ผลวิเคราะห์นี้อาศัยเพียง 5 จุดและใช้ความหนาแน่นแทนความพรุน จึงเป็นการตีความเชิงบ่งชี้ ผู้วิจัยเสนอให้วัดความพรุนเปิดและการดูดซึมน้ำแบบสุญญากาศเพื่อยืนยัน (ข้อความส่วนนี้เป็นการตีความและข้อเสนอแนะของผู้วิจัย)")

    anova_rows = []
    for series, order in (("I", TESTED1), ("II", TESTED2)):
        for age in (7, 14, 28):
            k = f"{series}_{age}"; dfb = len(order) - 1
            anova_rows.append(["ชุดที่ " + ("1" if series == "I" else "2"), str(age), f"{N['F_'+k]:.2f}", f"{dfb}, {N['df2_'+k]}", pv(N['p_'+k]), f"{N['eta_'+k]:.2f}", "มี" if N['p_'+k] < 0.05 else "ไม่มี"])
    b.table("ranova", "สรุปผล ANOVA ทางเดียวของกำลังอัดแยกตามชุดและอายุบ่ม", ["ชุด", "อายุ (วัน)", "F", "df (ระหว่าง, ภายใน)", "p", "η<sup>2</sup>", "ความแตกต่างระหว่างสูตร (α = 0.05)"], anova_rows, [1100, 1000, 1000, 1700, 1100, 1000, 2400], sz=21,
            note="หมายเหตุ คำนวณจากค่ารายก้อนที่ไม่รวมช่อง † ของ " + "{tab:rfc1} ข้อสมมติของ ANOVA (ความแปรปรวนเท่ากันและเป็นปกติ) ตรวจได้ยากเมื่อ n = 3 ผลจึงใช้เพื่อชี้ทิศทาง ไม่ใช่เพื่อประมาณขนาดอิทธิพลอย่างแม่นยำ")

    # ------------------------------------------------------------------ 4.4
    b.h2("4.4 ผลการทดสอบการดูดซึมน้ำ")
    b.p(ot(336, {"ตามสมการที่ 3-3": "ตาม{eq:abs}", "ตารางที่ 4-4 ตารางที่ 4-5 และภาพที่ 4-6": "{tab:rabs1} {tab:rabs2} และ{fig:rabs}"}).replace("ได้เลือกทดสอบเฉพาะสูตร Rab5% ซึ่งเป็นสูตรที่ให้กำลังต้านทานแรงอัดสูงที่สุดในกลุ่มที่ผสมถ่านชีวภาพ", "ทดสอบเฉพาะสูตร Rab5% ซึ่งเป็นสูตรที่ให้กำลังอัดสูงที่สุดในกลุ่มที่ผสมถ่านชีวภาพ (ตัวอย่างอายุ 14 และ 28 วัน)"))
    a1 = pd.read_csv(os.path.join(DATA, "absorption_series1_rab5.csv"))
    rows = []
    for r in a1.itertuples():
        rows.append([str(r.age_d), f"{r.wet_kg:.2f}", f"{r.dry_kg:.2f}", f"{r.abs_pct:.2f}"])
    b.table("rabs1", "ผลการทดสอบการดูดซึมน้ำที่ 72 ชั่วโมงของคอนกรีตบล็อกปูพื้น ชุดที่ 1 (สูตร Rab5%)", ["อายุ (วัน)", "มวลเปียก (กก.)", "มวลแห้ง (กก.)", "การดูดซึมน้ำ (%)"], rows, [1700, 2000, 2000, 2200], sz=21,
            note="หมายเหตุ ค่าการดูดซึมน้ำคำนวณจากมวลเปียกและมวลแห้งที่บันทึก ตรวจสอบแล้วตรงกับ{eq:abs} ทุกก้อน (ต่างไม่เกิน 0.005 %) ที่อายุ 7 วันไม่มีข้อมูล")
    b.p(f"การดูดซึมน้ำของ Rab5% อยู่ระหว่างร้อยละ {a1.abs_pct.min():.2f} ถึง {a1.abs_pct.max():.2f} เฉลี่ยร้อยละ {N['ab_rab5_all']:.2f} (14 วัน {N['ab14_Rab5']:.2f} และ 28 วัน {N['ab28_Rab5']:.2f}) ต่ำกว่าเกณฑ์ร้อยละ 5 ของ มอก. 2035-2565 และ ASTM C936 ({{c:tis2035,astmc936}}) มาก")
    a2 = pd.read_csv(os.path.join(DATA, "absorption_series2.csv"))
    rows = []
    flagged = {("RCA 10%", 14), ("RCA 15%", 14), ("RCA 15%", 28)}
    for r in a2.itertuples():
        mk = "‡" if (r.mix, r.age_d) in flagged else ""
        rows.append([r.mix if r.age_d == 7 else "", str(r.age_d), f"{r.s1:.2f}", f"{r.s2:.2f}", f"{r.s3:.2f}", f"{r.mean_reported:.2f}{mk}"])
    b.table("rabs2", "ผลการทดสอบการดูดซึมน้ำที่ 72 ชั่วโมงของคอนกรีตบล็อกปูพื้น ชุดที่ 2 (%)", ["สูตร", "อายุ (วัน)", "ก้อนที่ 1", "ก้อนที่ 2", "ก้อนที่ 3", "เฉลี่ย"], rows, [1700, 1300, 1400, 1400, 1400, 1500], sz=21,
            note="หมายเหตุ ‡ ค่าที่ต้องยืนยันด้วยการทดสอบซ้ำ ได้แก่ RCA 10% และ RCA 15% ที่ 14 วัน (สูงผิดปกติเทียบกับอายุอื่น) และ RCA 15% ที่ 28 วัน ซึ่งซ้ำกับค่าที่ 7 วันของสูตรเดียวกันทุกค่า (0.29 0.30 และ 0.61) ตารางสำหรับบันทึกผลทดสอบซ้ำอยู่ในภาคผนวก ข " + PH)
    b.fig("rabs", fp("r_abs_s2"), 15.0, "(ก) การดูดซึมน้ำที่ 72 ชั่วโมงของชุดที่ 2 จุดคือค่ารายก้อน เส้นประคือเกณฑ์ร้อยละ 5 (ข) ค่ารายก้อนทั้งหมดเทียบกับเส้นกริดความละเอียดของเครื่องชั่ง (0.01 กก. ต่อมวลก้อนประมาณ 3.3 กก. คิดเป็นร้อยละ 0.30) ผู้วิจัยสร้างภาพจาก{tab:rabs2}")
    b.p(f"ค่าการดูดซึมน้ำของชุดที่ 2 อยู่ระหว่างร้อยละ {a2[['s1','s2','s3']].min().min():.2f} ถึง {a2[['s1','s2','s3']].max().max():.2f} ต่ำกว่าเกณฑ์ร้อยละ 5 ของ มอก. 2035-2565 และ ASTM C936 และเกณฑ์ร้อยละ 6 ของ EN 1338 {{c:en1338}} ทุกค่า แต่มีข้อสังเกตด้านคุณภาพข้อมูลสามข้อ ข้อแรก {{fig:rabs}}(ข) แสดงว่าค่ารายก้อนเกือบทั้งหมดอยู่ที่ผลคูณของร้อยละ 0.30 สอดคล้องกับการชั่งละเอียด 0.01 กก. ที่มวลก้อนราว 3.3 กก. ความแตกต่างระหว่างสูตรที่ต่ำกว่าร้อยละ 0.3 จึงอยู่ในระดับความละเอียดของเครื่องชั่ง ไม่ควรตีความ ข้อสอง ค่า RCA 10% และ RCA 15% ที่ 14 วัน (ร้อยละ {N['ab14_RCA10']:.2f} และ {N['ab14_RCA15']:.2f}) สูงกว่าค่าที่ 7 และ 28 วันของสูตรเดียวกันมาก ร่างเดิมอธิบายว่าเป็นผลของมอร์ตาร์เดิมที่พรุนบน RCA ร่วมกับความแปรปรวนของการบ่ม แต่คำอธิบายนี้ไม่อธิบายว่าเหตุใดค่าที่ 7 วันซึ่งอายุน้อยกว่าจึงต่ำกว่าค่าที่ 14 วันมาก (RCA 10%: 0.60 เทียบ 2.73) เพราะการดูดซึมน้ำของก้อนควรลดลงตามอายุ ไม่ใช่เพิ่มขึ้น จึงเป็นไปได้ว่าเกิดจากการบันทึกหรือเตรียมตัวอย่างต่างจากอายุอื่น ข้อสาม ค่าของ RCA 15% ที่ 28 วันซ้ำกับค่าที่ 7 วันทุกค่า ซึ่งอาจเป็นการคัดลอกซ้ำ ทั้งสามรายการต้องทดสอบซ้ำก่อนใช้อ้างอิง ผู้วิจัยจึงไม่ใช้ค่าเหล่านี้สรุปแนวโน้มของการดูดซึมน้ำตามอัตรา RCA และสรุปได้เฉพาะว่าทุกสูตรต่ำกว่าเกณฑ์ (ข้อความส่วนนี้เป็นการตีความและข้อเสนอแนะของผู้วิจัย)")
    b.p("การดูดซึมน้ำของ RCA ที่แท้จริงควรสูงกว่าทรายเมื่อคิดเป็นวัสดุเดี่ยว ({c:nedeljkovic2021,verian2018}) และ Wang และคณะ (2019) {c:wangx2019} รายงานว่าบล็อกที่ใช้ RCA ดูดซึมน้ำมากขึ้น ผลของชุดที่ 2 ซึ่งแทนทรายด้วย RCA ไม่เกินร้อยละ 15 และอัดแน่นจึงยังไม่เห็นแนวโน้มดังกล่าวอย่างชัดเจน ทั้งนี้ต้องรอผลทดสอบซ้ำของสามรายการข้างต้นและทดสอบการดูดซึมน้ำของ RCA เองเพื่อยืนยัน")
